use super::*;

/// Every entity, id-sorted so output is stable.
pub fn list(store: &bsc_json_store::Store) -> Vec<Entity> {
    let mut out: Vec<Entity> = store
        .list()
        .iter()
        .filter_map(|raw| serde_json::from_str::<Entity>(raw).ok())
        .collect();
    out.sort_by(|a, b| a.id.cmp(&b.id));
    out
}
